INSERT INTO stage_definitions (code, sort_order, name, short_name, sla_value, sla_unit, sla_text, owner_party, service_scope, customer_status, is_terminal, regulation_ref, hint) VALUES
  ('draft', 1, 'Черновик заявки', 'Черновик', 0, 'none', '—', 'customer', NULL, 'draft', false, 'ТЗ №1', 'Заказчик заполняет форму на портале. Заявка ещё не подана.'),
  ('registered', 2, 'Зарегистрирована', 'Регистрация', 0, 'same_day', 'в день поступления', 'records', NULL, 'registered', false, 'п. 6', 'Регистрация в СП ЦА, ответственном за документооборот, и направление в ОР ПСД и филиал.'),
  ('tv_review', 3, 'Оценка технической возможности', 'Оценка ТВ', 5, 'working', '5 рабочих дней', 'orpsd', NULL, 'review', false, 'пп. 9, 16', 'Проверка по мастер-файлу «Реестр АМС и загрузки»; результат фиксируется с версией реестра.'),
  ('offer', 4, 'КП, договор, счёт', 'КП и договор', 1, 'operational', 'счёт — в день получения СЗ', 'orpsd', NULL, 'work', false, 'пп. 21, 32, 48, 84–85', 'Коммерческое предложение по Прейскуранту суммой позиций, проект договора, счёт в 1С.'),
  ('awaiting_payment', 5, 'Ожидание 100 % предоплаты', 'Оплата', 10, 'working', 'оферта 10 рабочих дней', 'customer', NULL, 'work', false, 'пп. 86–88, табл. 1', 'Ежедневный мониторинг поступления оплаты; по истечении оферты заявка закрывается.'),
  ('tu', 6, 'Выдача технических условий', 'ТУ', 5, 'working', '5 рабочих дней после полной оплаты', 'orpsd', 'ТУ', 'work', false, 'пп. 22–24', 'Разработка, согласование с филиалом, утверждение и направление ТУ Заявителю.'),
  ('psd', 7, 'Разработка ПСД', 'ПСД', 30, 'working', '30 рабочих дней, продление не более 15', 'orpsd', 'ПСД', 'work', false, 'пп. 33–42', 'Контрольные точки: исходные данные (3 р.д.), графическая часть, двухуровневая проверка СД, согласование с филиалом.'),
  ('smr_prep', 8, 'Подготовка к СМР', 'Подготовка СМР', 90, 'calendar', 'до 90 календарных дней на оборудование', 'customer', 'СМР', 'work', false, 'пп. 55–60', 'Заказчик передаёт оборудование по акту; филиал принимает; оформляется распоряжение на СМР.'),
  ('smr', 9, 'Выполнение СМР', 'СМР', 15, 'working', '15 рабочих дней', 'branch', 'СМР', 'work', false, 'п. 59', 'Работы выполняет филиал; по завершении оформляется технический АВР.'),
  ('avr', 10, 'АВР и ЭСФ', 'АВР и ЭСФ', 1, 'operational', '1 операционный день', 'accounting', NULL, 'work', false, 'пп. 66, 70, 90–92', 'Формирование АВР (Р-1 для ТУ и ПСД, № 2В для СМР — п. 70) и электронной счёт-фактуры, направление Заказчику.'),
  ('closing', 11, 'Приёмка Заказчиком', 'Приёмка', 10, 'working', '10 рабочих дней на замечания', 'customer', NULL, 'work', false, 'пп. 93–95', 'Без подтверждения и мотивированных замечаний в срок работы считаются принятыми в полном объёме.'),
  ('closed_done', 12, 'Исполнена', 'Исполнена', 0, 'none', '—', 'orpsd', NULL, 'done', true, 'п. 127', 'Договор считается исполненным после подписания всех предусмотренных документов.'),
  ('closed_rejected', 13, 'Отказано', 'Отказ', 2, 'working', 'ответ в 2 рабочих дня', 'orpsd', NULL, 'rejected', true, 'п. 19, табл. 1', 'Мотивированный письменный отказ; заявка закрывается и архивируется.'),
  ('closed_expired', 14, 'Закрыта по истечении оферты', 'Оферта истекла', 0, 'none', '—', 'orpsd', NULL, 'rejected', true, 'табл. 1', 'Оплата не поступила в течение 10 рабочих дней; заявка закрыта с письменным уведомлением.'),
  ('closed_cancelled', 15, 'Расторгнута', 'Расторжение', 0, 'none', '—', 'orpsd', NULL, 'rejected', true, 'пп. 96–97', 'Соглашение о расторжении; при необходимости — заявка на возврат денежных средств.')
