INSERT INTO automation_rules (id, trigger_key, event_title, action_key, description, regulation_ref, timer_days, enabled) VALUES
  (1, 'request_registered', 'Заявка зарегистрирована', 'assign_branch_and_curator', 'Определить филиал и курирующего заместителя директора по объекту; направить заявку в ОР ПСД и филиал; запустить срок ответа 5 рабочих дней', 'пп. 6, 9, Приложение 7', 5, true),
  (2, 'tv_data_missing', 'Недостаточно данных для оценки ТВ', 'create_memo', 'Сформировать служебную записку в филиал с таймером 3 рабочих дня и напоминанием курирующему заместителю директора', 'п. 10', 3, true),
  (3, 'tv_capacity_near_limit', 'Загрузка приближается к предельным значениям', 'flag_verification_calc', 'Показать расчётную загрузку объекта и яруса, остаток ёмкости и мощности; запросить решение инженера о поверочном расчёте. Числовой порог Регламентом не установлен — система его не задаёт', 'п. 16.4, Приложение 8', NULL, true),
  (4, 'tv_confirmed', 'Техническая возможность подтверждена', 'create_offer_tasks', 'Сформировать КП по Прейскуранту суммой всех позиций заявки, проект договора и служебную записку на выставление счёта', 'пп. 21, 32, 48', NULL, true),
  (5, 'contract_signed', 'Договор подписан', 'request_invoice', 'Направить СЗ в СП ЦА, ответственное за расчёты с контрагентами; счёт формируется в 1С в день получения СЗ и направляется Заказчику', 'пп. 84–85', 1, true),
  (6, 'payment_pending', 'Оплата не поступила', 'remind_customer', 'Ежедневный мониторинг поступления оплаты; письмо-напоминание Заказчику; по истечении срока оферты (10 рабочих дней) — закрытие заявки с письменным уведомлением', 'п. 88, табл. 1', 10, true),
  (7, 'payment_received', 'Поступила 100 % предоплата', 'start_service_timer', 'Запустить срок оказания услуги: ТУ — 5 рабочих дней, ПСД — 30 рабочих дней; направить СЗ в филиал о возможности приёма оборудования', 'пп. 24, 33, 54', NULL, true),
  (8, 'psd_control_point', 'Разработка ПСД, третий рабочий день', 'create_control_point', 'Контрольная точка «проверка полноты и корректности исходных данных»; при неполноте — запрос в филиал с уведомлением курирующего заместителя директора', 'п. 34.1', 3, true),
  (9, 'psd_deadline_near', 'До срока ПСД пять дней, объём не закрыт', 'offer_extension', 'Предложить продление не более чем на 15 рабочих дней с письменным уведомлением Заказчика', 'п. 33', 15, true),
  (10, 'equipment_due_soon', 'До истечения срока предоставления оборудования десять дней', 'remind_customer', 'Направить уведомление-напоминание Заказчику; при просрочке — претензия, далее приостановление и (или) расторжение договора', 'пп. 56–57', 10, true),
  (11, 'transfer_act_approved', 'Акт приёма-передачи оборудования завизирован', 'start_smr_timer', 'Запустить срок выполнения СМР 15 рабочих дней; поставить задачу на подготовку распоряжения', 'пп. 58–60', 15, true),
  (12, 'stage_breached', 'Нарушен срок этапа', 'escalate', 'Эскалация 1-го уровня в день выявления — курирующему заместителю директора филиала с копией директору; при неустранении в течение 2 рабочих дней — 2-й уровень курирующему члену Правления', 'п. 100', 2, true),
  (13, 'technical_avr_signed', 'Технический акт выполненных работ подписан', 'notify_accounting', 'Уведомить СП ЦА, ответственное за расчёты с контрагентами: АВР и электронная счёт-фактура оформляются не позднее 1 операционного дня', 'пп. 66, 90–91', 1, true),
  (14, 'customer_refused_act', 'Заказчик отказался подписать технический АВР', 'create_legal_task', 'Служебная записка филиала с причиной и подтверждающими документами; при разногласиях — претензионный порядок и СЗ в СП ЦА, ответственное за юридические вопросы', 'пп. 67–69, табл. 1', 3, true),
  (15, 'avr_silence_expired', 'АВР не подписан и замечания не поступили в течение 10 рабочих дней', 'close_as_accepted', 'Работы считаются принятыми в полном объёме без замечаний; дополнительное оформление и повторное подписание не требуются', 'пп. 94–95', 10, true),
  (16, 'contract_terminated', 'Поступило письмо о расторжении договора', 'create_legal_task', 'Подготовка соглашения о расторжении; при необходимости — заявка на возврат денежных средств', 'пп. 96–97', NULL, true),
  (17, 'tu_expiring', 'Истекает срок действия технических условий', 'notify_expiry', 'Уведомить ОР ПСД и Заказчика: срок действия ТУ не более 6 месяцев, продление допускается только по запросу до истечения срока', 'п. 31', NULL, true),
  (18, 'psd_conditions_expiring', 'Истекают три месяца с даты получения утверждённой ПСД', 'require_tv_recheck', 'Условия установки оборудования перестают быть актуальными — требуется повторная оценка технической возможности и при необходимости актуализация проектных решений', 'п. 47', NULL, true),
  (19, 'mount_act_received', 'Получен технический акт монтажа или демонтажа', 'update_registry_task', 'Задача СП ЦА, ответственному за технический учёт активов: внести изменения в реестр в течение 1 рабочего дня; при высвобождении ёмкости — уведомление коммерческому блоку', 'пп. 13–14', 1, true),
  (20, 'monthly_branch_report', 'Наступило 5-е число месяца', 'build_report', 'Подготовить отчёт филиала об исполненных и неисполненных договорах за прошедший месяц для подтверждения и направления в установленном порядке', 'п. 105', NULL, true),
  (21, 'annual_summary_report', 'Наступило 1 марта', 'build_report', 'Сформировать сводный отчёт по производственным показателям филиалов за отчётный год по исполненным, принятым и оплаченным договорам', 'пп. 107, 109', NULL, true)
