-- Конфигурация процесса. Файл сгенерирован: npm run seed:sql
-- Источник истины — src/process/{stages,transitions,rules}.ts (покрыты тестами).
-- Править вручную не нужно: изменения вносятся в код либо администратором в интерфейсе.

BEGIN;

-- Этапы обработки заявки. Норматив и ответственная сторона — из Регламента.
ON CONFLICT (code) DO UPDATE SET
  sort_order = excluded.sort_order, name = excluded.name, short_name = excluded.short_name,
  sla_value = excluded.sla_value, sla_unit = excluded.sla_unit, sla_text = excluded.sla_text,
  owner_party = excluded.owner_party, service_scope = excluded.service_scope,
  customer_status = excluded.customer_status, is_terminal = excluded.is_terminal,
  regulation_ref = excluded.regulation_ref, hint = excluded.hint;

-- Допустимые переходы. Условия проверяются движком по ключу guard_key.
ON CONFLICT (from_code, to_code) DO UPDATE SET
  title = excluded.title, guard_key = excluded.guard_key,
  roles = excluded.roles, regulation_ref = excluded.regulation_ref;

-- Правила автоматизации. Каждое несёт ссылку на пункт Регламента.
ON CONFLICT (id) DO UPDATE SET
  trigger_key = excluded.trigger_key, event_title = excluded.event_title,
  action_key = excluded.action_key, description = excluded.description,
  regulation_ref = excluded.regulation_ref, timer_days = excluded.timer_days;

-- Производственный календарь: фиксированные праздничные дни РК.
-- Переносы выходных и Курбан-айт вносит администратор ДИТ ежегодно.
ON CONFLICT (day) DO UPDATE SET kind = excluded.kind, source = excluded.source;

-- Настройки, вынесенные из кода.
ON CONFLICT (key) DO UPDATE SET
  value = excluded.value, description = excluded.description, regulation_ref = excluded.regulation_ref;

COMMIT;
